// prepareRepository signs every staged file of every named artifact with the
// publication key, adds checksums, and writes one deterministic bundle whose
// entries keep the staging repository's layout.
func prepareRepository(ctx context.Context, root string, c Config) (Prepared, error) {
	artifacts, issues := scanStaging(root, c)
	if len(issues) > 0 {
		return Prepared{}, fmt.Errorf("staging changed since preflight: %s", issues[0].Problem)
	}
	files := map[string][]byte{}
	groupPath := strings.ReplaceAll(c.GroupID, ".", "/")
	for _, id := range c.Artifacts {
		a := artifacts[id]
		if a == nil {
			return Prepared{}, fmt.Errorf("artifact %s is not staged", id)
		}
		for name, path := range a.Files {
			data, err := os.ReadFile(path)
			if err != nil {
				return Prepared{}, err
			}
			files[groupPath+"/"+id+"/"+c.Version+"/"+name] = data
		}
	}
	epoch, err := commitEpoch(root)
	if err != nil {
		return Prepared{}, err
	}
	key, err := ensureKey(strings.TrimSpace(os.Getenv("AX_MAVEN_SIGNING_KEY")), c.GroupID+" release signing key", "", epoch)
	if err != nil {
		return Prepared{}, err
	}
	for _, name := range sortedKeys(files) {
		sig, err := sign(key.entity, files[name], epoch)
		if err != nil {
			return Prepared{}, fmt.Errorf("signing %s: %w", name, err)
		}
		files[name+".asc"] = sig
		addChecksums(files, name, files[name])
		addChecksums(files, name+".asc", sig)
	}
	output, ok := safePath(root, RepositoryBundlePath(c))
	if !ok {
		return Prepared{}, fmt.Errorf("unsafe bundle path %s", RepositoryBundlePath(c))
	}
	if err := os.MkdirAll(filepath.Dir(output), 0o755); err != nil {
		return Prepared{}, err
	}
	if err := writeBundle(output, "", files, epoch); err != nil {
		return Prepared{}, err
	}
	publicKey, err := serializePublicKey(key.entity)
	if err != nil {
		return Prepared{}, err
	}
	return Prepared{Bundle: output, SigningKey: key.path, Fingerprint: key.fingerprint, PublicKey: publicKey, Files: sortedKeys(files)}, nil
}

// deploymentName is the human label Central shows for the deployment.
func deploymentName(c Config) string {
	if c.ArtifactID != "" {
		return c.GroupID + ":" + c.ArtifactID + ":" + c.Version
	}
	return fmt.Sprintf("%s:%s (%d artifacts)", c.GroupID, c.Version, len(c.Artifacts))
}
